SELECT
    id,
    plan_name AS planName,
    patient_id AS patientId,
    plan_type_id AS planTypeId,
    org_id AS orgId,
    status,
    crt_time AS crtTime,
    dentist_id AS dentistId
FROM treat_plan_record


    AND org_id = #{query.orgId}


    AND plan_name like CONCAT(CONCAT('%',#{query.planName}),'%')


    AND patient_id = #{query.patientId}


    AND status in

      #{item}



    AND plan_type_id = #{query.planTypeId}



      and DATE_FORMAT(crt_time, '%Y-%m-%d') >= #{query.startDate}


      and DATE_FORMAT(crt_time, '%Y-%m-%d') <= #{query.endDate}




      and DATE_FORMAT(crt_time, '%Y-%m') >= #{query.startDate}


      and DATE_FORMAT(crt_time, '%Y-%m') <= #{query.endDate}




      and DATE_FORMAT(crt_time, '%Y') >= #{query.startDate}


      and DATE_FORMAT(crt_time, '%Y') <= #{query.endDate}



ORDER BY crt_time DESC

SELECT
    org_id AS orgId,
    dentist_id AS dentistId,
    plan_type_id AS planTypeId,
    count(*) AS planNum
FROM treat_plan_record


    AND plan_type_id = #{query.planTypeId}


    AND org_id in

      #{item}



    AND dentist_id in

      #{item}




      and DATE_FORMAT(crt_time, '%Y-%m-%d') >= #{query.startDate}


      and DATE_FORMAT(crt_time, '%Y-%m-%d') <= #{query.endDate}




      and DATE_FORMAT(crt_time, '%Y-%m') >= #{query.startDate}


      and DATE_FORMAT(crt_time, '%Y-%m') <= #{query.endDate}




      and DATE_FORMAT(crt_time, '%Y') >= #{query.startDate}


      and DATE_FORMAT(crt_time, '%Y') <= #{query.endDate}



GROUP BY org_id, dentist_id, plan_type_id
ORDER BY org_id, dentist_id, plan_type_id

SELECT
    id AS planId,
    patient_id AS patientId,
    plan_name AS planName,
    dentist_id AS dentistId,
    crt_time AS crtTime,
    CASE
    WHEN status=0 THEN '未确认'
    WHEN status=1 THEN '已确认'
    WHEN status=2 THEN '进行中'
    WHEN status=3 THEN '全部完成'
    WHEN status=4 THEN '提前终止'
    END
    AS status
FROM treat_plan_record


    AND org_id = #{query.orgId}


    AND dentist_id = #{query.dentistId}


    AND plan_type_id = #{query.planTypeId}



      and DATE_FORMAT(crt_time, '%Y-%m-%d') >= #{query.startDate}


      and DATE_FORMAT(crt_time, '%Y-%m-%d') <= #{query.endDate}




      and DATE_FORMAT(crt_time, '%Y-%m') >= #{query.startDate}


      and DATE_FORMAT(crt_time, '%Y-%m') <= #{query.endDate}




      and DATE_FORMAT(crt_time, '%Y') >= #{query.startDate}


      and DATE_FORMAT(crt_time, '%Y') <= #{query.endDate}



ORDER BY crt_time DESC
